 CREATE PROCEDURE [dbo].[API_BangThueTNCN]
(
    @Keyword NVARCHAR(200) = ''
)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        *
    FROM dbo.HR_BangThueTNCNTbl
    ORDER BY Bac ASC;
END

CREATE PROCEDURE [dbo].[API_BangThueTNCN_V2]
    @List varchar(50),
    @Keyword nvarchar(200) = N'',
    @SortColumn varchar(50) = '',
    @SortDir varchar(10) = '',
    @Data nvarchar(max) = N'',
    @UserName varchar(100) = '',
    @BranchID varchar(max) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @List = LTRIM(RTRIM(ISNULL(@List, '')));
    SET @Keyword = LTRIM(RTRIM(ISNULL(@Keyword, N'')));
    SET @SortColumn = LTRIM(RTRIM(ISNULL(@SortColumn, '')));
    SET @SortDir = UPPER(LTRIM(RTRIM(ISNULL(@SortDir, ''))));
    SET @Data = LTRIM(RTRIM(ISNULL(@Data, N'')));
    SET @UserName = LTRIM(RTRIM(ISNULL(@UserName, '')));
    SET @BranchID = LTRIM(RTRIM(ISNULL(@BranchID, '')));

    DECLARE @CurrentProcedure sysname = OBJECT_NAME(@@PROCID);
    IF (
        SELECT COUNT(*)
        FROM dbo.WA_API AS A
        WHERE A.[list] = @List
          AND A.[func] = 'View'
          AND LOWER(LTRIM(RTRIM(A.[SQL]))) = LOWER(@CurrentProcedure)
    ) <> 1
        THROW 52101, N'WA_API View V2 chưa được đăng ký duy nhất cho form.', 1;

    IF @UserName = ''
        THROW 52102, N'Thiếu ngữ cảnh người dùng.', 1;

    DECLARE @UserGroupID varchar(50), @UserBranches varchar(max);
    SELECT @UserGroupID = U.UserGroupID,
           @UserBranches = U.BranchID
    FROM dbo.SY_User AS U
    WHERE U.UserName = @UserName
      AND ISNULL(U.Disable, 0) = 0;

    IF @UserGroupID IS NULL
        THROW 52103, N'Người dùng không hợp lệ hoặc đã bị khóa.', 1;

    /* PHASE2_BRANCH_FAIL_CLOSED */
    IF LOWER(@UserGroupID) <> 'admin'
    BEGIN
        IF LTRIM(RTRIM(ISNULL(@UserBranches, ''))) = ''
            THROW 52118, N'Người dùng không phải admin chưa được gán chi nhánh; từ chối theo nguyên tắc fail-closed.', 1;
        IF @BranchID = ''
            THROW 52115, N'Thiếu ngữ cảnh chi nhánh của người dùng.', 1;
        IF EXISTS (
            SELECT 1
            FROM STRING_SPLIT(@BranchID, ',') AS Requested
            WHERE LTRIM(RTRIM(Requested.[value])) <> ''
              AND NOT EXISTS (
                  SELECT 1
                  FROM STRING_SPLIT(@UserBranches, ',') AS Allowed
                  WHERE UPPER(LTRIM(RTRIM(Allowed.[value]))) = UPPER(LTRIM(RTRIM(Requested.[value])))
              )
        )
            THROW 52116, N'Chi nhánh nằm ngoài phạm vi người dùng.', 1;
    END;

    DECLARE @MenuID varchar(50), @SkipPermission bit = 0;
    SELECT TOP (1)
        @MenuID = M.MenuID,
        @SkipPermission = ISNULL(M.isNotCheckPermission, 0)
    FROM dbo.WA_Menu AS M
    WHERE M.FormName = @List
      AND ISNULL(M.isDisable, 0) = 0
    ORDER BY M.MenuID;

    IF @MenuID IS NULL
        THROW 52104, N'Form chưa có menu hoạt động để kiểm tra quyền.', 1;

    IF LOWER(@UserGroupID) <> 'admin' AND @SkipPermission = 0
    BEGIN
        DECLARE @GroupCanRun bit, @UserCanRun bit;
        SELECT @GroupCanRun = P.IsRun
        FROM dbo.WA_UserGroupPermisstion AS P
        WHERE P.UserGroupID = @UserGroupID
          AND P.MenuID = @MenuID;

        SELECT @UserCanRun = P.IsRun
        FROM dbo.WA_UserPermisstion AS P
        WHERE P.UserName = @UserName
          AND P.MenuID = @MenuID;

        IF ISNULL(@UserCanRun, ISNULL(@GroupCanRun, 0)) <> 1
            THROW 52105, N'Không có quyền xem dữ liệu của form.', 1;
    END;

    DECLARE @RegistryCount int, @RegistryTable sysname, @RegistryPrimaryKey sysname;
    SELECT
        @RegistryCount = COUNT(*),
        @RegistryTable = MIN(LTRIM(RTRIM(L.TableName))),
        @RegistryPrimaryKey = MIN(LTRIM(RTRIM(L.PrimaryKey)))
    FROM dbo.SY_FrmLstTbl AS L
    WHERE L.FormID = @List;

    IF ISNULL(@RegistryCount, 0) <> 1
       OR LTRIM(RTRIM(ISNULL(@RegistryTable, ''))) = ''
       OR LTRIM(RTRIM(ISNULL(@RegistryPrimaryKey, ''))) = ''
        THROW 52106, N'SY_FrmLstTbl chưa có duy nhất TableName/PrimaryKey cho View V2.', 1;

    DECLARE @TableObjectID int = COALESCE(
        OBJECT_ID(@RegistryTable, N'U'),
        OBJECT_ID(N'dbo.' + @RegistryTable, N'U')
    );
    DECLARE @PhysicalSchema sysname, @PhysicalTable sysname;
    SELECT @PhysicalSchema = S.name, @PhysicalTable = T.name
    FROM sys.tables AS T
    INNER JOIN sys.schemas AS S ON S.schema_id = T.schema_id
    WHERE T.object_id = @TableObjectID;

    IF @TableObjectID IS NULL OR @PhysicalSchema IS NULL OR @PhysicalTable IS NULL
        THROW 52107, N'Không tìm thấy bảng nghiệp vụ đã đăng ký.', 1;

    IF EXISTS (
        SELECT 1
        FROM sys.columns AS C
        JOIN sys.types AS T ON T.user_type_id = C.user_type_id
        WHERE C.object_id = @TableObjectID
          AND (
                LOWER(C.name) IN ('content', 'base64content', 'filecontent', 'binarydata', 'password', 'passwordhash',
                                  'token', 'refreshtoken', 'secret', 'rawsql', 'commandtext')
             OR LOWER(T.name) IN ('binary', 'varbinary', 'image', 'timestamp', 'rowversion', 'xml', 'text', 'ntext',
                                  'sql_variant', 'geography', 'geometry', 'hierarchyid')
          )
    )
        THROW 52108, N'Pilot có cột kỹ thuật/blob thuộc deny-list; MAIN_TABLE_STAR bị chặn.', 1;

    IF EXISTS (
        SELECT 1
        FROM sys.columns
        WHERE object_id = @TableObjectID
          AND LOWER(name) IN ('branchid', 'tenantid', 'companyid', 'donviid')
    )
        THROW 52109, N'Pilot không còn là danh mục toàn cục; cần bổ sung isolation trước khi chạy.', 1;

    -- IF EXISTS (
    --     SELECT 1
    --     FROM sys.columns
    --     WHERE object_id = @TableObjectID
    --       AND (
    --             LOWER(name) LIKE '%password%'
    --          OR LOWER(name) LIKE '%token%'
    --          OR LOWER(name) LIKE '%secret%'
    --          OR LOWER(name) LIKE '%bank%'
    --          OR LOWER(name) LIKE '%cccd%'
    --          OR LOWER(name) LIKE '%cmnd%'
    --          OR LOWER(name) LIKE '%bhxh%'
    --          OR LOWER(name) LIKE '%salary%'
    --          OR LOWER(name) LIKE '%luong%'
    --          OR LOWER(name) LIKE '%email%'
    --          OR LOWER(name) LIKE '%phone%'
    --          OR LOWER(name) LIKE '%dienthoai%'
    --          OR LOWER(name) LIKE '%diachi%'
    --       )
    -- )
    --     THROW 52110, N'Pilot xuất hiện cột dữ liệu nhạy cảm ngoài contract danh mục; cần audit lại.', 1;

    DECLARE @HasSoftDelete bit = CASE WHEN EXISTS (
        SELECT 1
        FROM sys.columns AS C
        JOIN sys.types AS T ON T.user_type_id = C.user_type_id
        WHERE C.object_id = @TableObjectID
          AND LOWER(C.name) = 'isdeleted'
          AND LOWER(T.name) = 'bit'
    ) THEN 1 ELSE 0 END;

    IF EXISTS (
        SELECT 1
        FROM sys.columns AS C
        JOIN sys.types AS T ON T.user_type_id = C.user_type_id
        WHERE C.object_id = @TableObjectID
          AND LOWER(C.name) = 'isdeleted'
          AND LOWER(T.name) <> 'bit'
    )
        THROW 52113, N'IsDeleted của pilot phải có kiểu bit.', 1;

    IF NOT EXISTS (
        SELECT 1
        FROM sys.columns
        WHERE object_id = @TableObjectID
          AND LOWER(name) = LOWER(@RegistryPrimaryKey)
    )
        THROW 52111, N'Pilot thiếu khóa chính vật lý đã đăng ký.', 1;

    IF @Data <> N'' AND (ISJSON(@Data) <> 1 OR LEFT(@Data, 1) <> N'{')
        THROW 52112, N'JsonData bộ lọc không hợp lệ.', 1;

    IF @Data = N'' SET @Data = N'{}';

    /* PHASE2_UNIFIED_FIELD_CONTRACT: field mới an toàn dùng cùng sys.columns với metadata và Save V2. */
    IF ISJSON(@Data) = 1 AND EXISTS (
        SELECT LOWER(J.[key])
        FROM OPENJSON(@Data) AS J
        GROUP BY LOWER(J.[key])
        HAVING COUNT(*) > 1
    )
        THROW 52117, N'JsonData có khóa lặp; từ chối contract không xác định.', 1;

    DECLARE @DataBranchID nvarchar(max) = NULL;
    IF ISJSON(@Data) = 1
        SELECT TOP (1) @DataBranchID = NULLIF(LTRIM(RTRIM(CONVERT(nvarchar(max), J.[value]))), N'')
        FROM OPENJSON(@Data) AS J
        WHERE LOWER(J.[key]) = 'branchid';

    IF @DataBranchID IS NOT NULL
    BEGIN
        IF LOWER(@UserGroupID) <> 'admin' AND @BranchID = ''
            THROW 52119, N'Thiếu ngữ cảnh chi nhánh trong request View.', 1;
        IF @BranchID <> '' AND EXISTS (
            SELECT 1
            FROM STRING_SPLIT(@DataBranchID, ',') AS Requested
            WHERE LTRIM(RTRIM(Requested.[value])) <> ''
              AND NOT EXISTS (
                  SELECT 1
                  FROM STRING_SPLIT(@BranchID, ',') AS ContextBranch
                  WHERE UPPER(LTRIM(RTRIM(ContextBranch.[value]))) = UPPER(LTRIM(RTRIM(Requested.[value])))
              )
        )
            THROW 52120, N'BranchID trong JsonData vượt ngữ cảnh request.', 1;
    END;

    IF ISJSON(@Data) = 1 AND EXISTS (
        SELECT 1
        FROM OPENJSON(@Data) AS J
        WHERE LOWER(J.[key]) NOT IN ('keyword', 'branchid')
          AND NOT EXISTS (
              SELECT 1
              FROM sys.columns AS C
              JOIN sys.types AS T ON T.user_type_id = C.user_type_id
              WHERE C.object_id = @TableObjectID
                AND LOWER(C.name) COLLATE DATABASE_DEFAULT = LOWER(J.[key]) COLLATE DATABASE_DEFAULT
                AND C.is_computed = 0
                AND LOWER(T.name) NOT IN ('binary', 'varbinary', 'image', 'timestamp', 'rowversion', 'xml', 'text', 'ntext',
                                          'sql_variant', 'geography', 'geometry', 'hierarchyid')
                AND LOWER(C.name) NOT IN ('content', 'base64content', 'filecontent', 'binarydata', 'password', 'passwordhash',
                                          'token', 'refreshtoken', 'secret', 'rawsql', 'commandtext',
                                          'usercreate', 'createdby', 'createby', 'datecreate', 'createddate', 'createdat',
                                          'userupdate', 'updatedby', 'updateby', 'dateupdate', 'updateddate', 'updatedat',
                                          'isdeleted', 'userdelete', 'deletedby', 'deleteby', 'datedelete', 'deleteddate', 'deletedat')
          )
    )
        THROW 52114, N'Bộ lọc chứa field không thuộc Form Contract V2.', 1;

    IF @SortColumn = '' AND @SortDir = '' SET @SortDir = 'DESC';
    IF @SortDir NOT IN ('ASC', 'DESC') SET @SortDir = 'ASC';
    DECLARE @ResolvedSortColumn sysname;
    SELECT TOP (1) @ResolvedSortColumn = C.name
    FROM sys.columns AS C
    JOIN sys.types AS T ON T.user_type_id = C.user_type_id
    WHERE C.object_id = @TableObjectID
      AND LOWER(C.name) COLLATE DATABASE_DEFAULT = LOWER(CASE WHEN @SortColumn = '' THEN @RegistryPrimaryKey ELSE @SortColumn END) COLLATE DATABASE_DEFAULT
      AND C.is_computed = 0
      AND LOWER(T.name) NOT IN ('binary', 'varbinary', 'image', 'timestamp', 'rowversion', 'xml', 'text', 'ntext',
                                'sql_variant', 'geography', 'geometry', 'hierarchyid')
      AND LOWER(C.name) NOT IN ('content', 'base64content', 'filecontent', 'binarydata', 'password', 'passwordhash',
                                'token', 'refreshtoken', 'secret', 'rawsql', 'commandtext',
                                'usercreate', 'createdby', 'createby', 'datecreate', 'createddate', 'createdat',
                                'userupdate', 'updatedby', 'updateby', 'dateupdate', 'updateddate', 'updatedat',
                                'isdeleted', 'userdelete', 'deletedby', 'deleteby', 'datedelete', 'deleteddate', 'deletedat');

    IF @ResolvedSortColumn IS NULL
        THROW 52121, N'Cột sắp xếp không thuộc Form Contract V2.', 1;

    /*
      MAIN_TABLE_STAR_APPROVED.
      TableName chỉ lấy từ SY_FrmLstTbl rồi đối chiếu sys.tables; giá trị filter/sort luôn parameterized.
      Danh sách field không ghép tay: T.* tự nhận cột vật lý mới, metadata lấy cùng nguồn sys.columns.
    */
    DECLARE @Sql nvarchar(max) = N'
        SELECT T.*
        FROM ' + QUOTENAME(@PhysicalSchema) + N'.' + QUOTENAME(@PhysicalTable) + N' AS T
        CROSS APPLY (
            SELECT (SELECT T.* FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES) AS RowJson
        ) AS R
        OUTER APPLY (
            SELECT TOP (1) J.[value] AS SortValue, J.[type] AS SortJsonType
            FROM OPENJSON(R.RowJson) AS J
            WHERE LOWER(J.[key]) COLLATE DATABASE_DEFAULT = LOWER(@ResolvedSortColumn) COLLATE DATABASE_DEFAULT
        ) AS S
        OUTER APPLY (
            SELECT TOP (1) J.[value] AS PrimaryValue, J.[type] AS PrimaryJsonType
            FROM OPENJSON(R.RowJson) AS J
            WHERE LOWER(J.[key]) COLLATE DATABASE_DEFAULT = LOWER(@RegistryPrimaryKey) COLLATE DATABASE_DEFAULT
        ) AS P
        WHERE (
            @Keyword = N''''
            OR EXISTS (
                SELECT 1
                FROM OPENJSON(R.RowJson) AS K
                WHERE K.[type] <> 0
                  AND EXISTS (
                      SELECT 1
                      FROM sys.columns AS C
                      JOIN sys.types AS TY ON TY.user_type_id = C.user_type_id
                      WHERE C.object_id = @TableObjectID
                        AND LOWER(C.name) COLLATE DATABASE_DEFAULT = LOWER(K.[key]) COLLATE DATABASE_DEFAULT
                        AND C.is_computed = 0
                        AND LOWER(TY.name) NOT IN (''binary'', ''varbinary'', ''image'', ''timestamp'', ''rowversion'', ''xml'', ''text'', ''ntext'',
                                                   ''sql_variant'', ''geography'', ''geometry'', ''hierarchyid'')
                        AND LOWER(C.name) NOT IN (''content'', ''base64content'', ''filecontent'', ''binarydata'', ''password'', ''passwordhash'',
                                                  ''token'', ''refreshtoken'', ''secret'', ''rawsql'', ''commandtext'',
                                                  ''usercreate'', ''createdby'', ''createby'', ''datecreate'', ''createddate'', ''createdat'',
                                                  ''userupdate'', ''updatedby'', ''updateby'', ''dateupdate'', ''updateddate'', ''updatedat'',
                                                  ''isdeleted'', ''userdelete'', ''deletedby'', ''deleteby'', ''datedelete'', ''deleteddate'', ''deletedat'')
                  )
                  AND CONVERT(nvarchar(4000), K.[value]) LIKE N''%'' + @Keyword + N''%''
            )
        )
          AND NOT EXISTS (
              SELECT 1
              FROM OPENJSON(@Data) AS F
              WHERE LOWER(F.[key]) NOT IN (''keyword'', ''branchid'')
                AND NOT EXISTS (
                    SELECT 1
                    FROM OPENJSON(R.RowJson) AS V
                    WHERE LOWER(V.[key]) COLLATE DATABASE_DEFAULT = LOWER(F.[key]) COLLATE DATABASE_DEFAULT
                      AND V.[type] <> 0
                      AND CONVERT(nvarchar(4000), V.[value]) LIKE N''%'' + CONVERT(nvarchar(4000), F.[value]) + N''%''
                )
          )
          /* PHASE2_SOFT_DELETE_FILTER */
          AND (
              @HasSoftDelete = 0
              OR NOT EXISTS (
                  SELECT 1
                  FROM OPENJSON(R.RowJson) AS SD
                  WHERE LOWER(SD.[key]) = ''isdeleted''
                    AND TRY_CONVERT(bit, SD.[value]) = 1
              )
          )
        ORDER BY
            CASE WHEN @SortDir = ''ASC''  AND S.SortJsonType = 2 THEN TRY_CONVERT(decimal(38, 10), S.SortValue) END ASC,
            CASE WHEN @SortDir = ''DESC'' AND S.SortJsonType = 2 THEN TRY_CONVERT(decimal(38, 10), S.SortValue) END DESC,
            CASE WHEN @SortDir = ''ASC''  AND S.SortJsonType <> 2 THEN S.SortValue END ASC,
            CASE WHEN @SortDir = ''DESC'' AND S.SortJsonType <> 2 THEN S.SortValue END DESC,
            CASE WHEN P.PrimaryJsonType = 2 THEN TRY_CONVERT(decimal(38, 10), P.PrimaryValue) END DESC,
            CASE WHEN P.PrimaryJsonType <> 2 THEN P.PrimaryValue END DESC;';

    EXEC sys.sp_executesql
        @Sql,
        N'@Keyword nvarchar(200), @Data nvarchar(max), @ResolvedSortColumn sysname, @RegistryPrimaryKey sysname,
          @SortDir varchar(10), @HasSoftDelete bit, @TableObjectID int',
        @Keyword = @Keyword,
        @Data = @Data,
        @ResolvedSortColumn = @ResolvedSortColumn,
        @RegistryPrimaryKey = @RegistryPrimaryKey,
        @SortDir = @SortDir,
        @HasSoftDelete = @HasSoftDelete,
        @TableObjectID = @TableObjectID;
END;

CREATE PROCEDURE [dbo].[API_CaLamViec]
(
    @Keyword NVARCHAR(200) = ''
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @Keyword = ISNULL(@Keyword, '');

    SELECT
       *
    FROM dbo.HR_SapCaTbl
    WHERE
        @Keyword = ''
        OR SapCaID LIKE '%' + @Keyword + '%'
        OR TenBangCa LIKE N'%' + @Keyword + '%'
    ORDER BY SapCaID DESC;
END

CREATE  PROCEDURE [dbo].[API_CandidateAttach_SaveAvatar]
    @List VARCHAR(50),
    @Data NVARCHAR(MAX),
    @UserName VARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        -- Extract CandidateID from JSON
        DECLARE @CandidateID VARCHAR(50) = JSON_VALUE(@Data, '$.CandidateID');
        DECLARE @FileType INT = CAST(JSON_VALUE(@Data, '$.FileType') AS INT);

        IF @CandidateID IS NULL OR @CandidateID = ''
        BEGIN
            SELECT -1 AS code, N'Lỗi: Không tìm thấy mã ứng viên!' AS msg;
            RETURN;
        END

        -- If uploading Avatar (FileType = 1) -> Find old Avatar to overwrite (UPDATE)
        IF @FileType = 1
        BEGIN
            DECLARE @ExistingID VARCHAR(50);
            SELECT TOP 1 @ExistingID = UserAutoID
            FROM HR_CandidateAttachTbl
            WHERE (CandidateID = @CandidateID) AND FileType = 1;

            IF @ExistingID IS NOT NULL
            BEGIN
                -- If Avatar exists -> Inject UserAutoID into JSON and change IsEdit = 1
                SET @Data = JSON_MODIFY(@Data, '$.UserAutoID', @ExistingID);
                SET @Data = JSON_MODIFY(@Data, '$.IsEdit', 1);
            END
        END

        -- Delegate to API_LuuDong
        EXEC API_LuuDong @List = @List, @Data = @Data, @UserName = @UserName;

    END TRY
    BEGIN CATCH
        SELECT -1 AS code, ERROR_MESSAGE() AS msg;
    END CATCH
END

CREATE  PROCEDURE [dbo].[API_ComboPersonStatus]
(
    @Keyword NVARCHAR(200) = '',
    @UserName VARCHAR(50) = ''
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        PersonStatus AS [Mã],
        PersonStatusName AS [Tên]
    FROM dbo.HR_PersonStatusTbl
    WHERE (@Keyword = '' OR PersonStatusName LIKE N'%' + @Keyword + '%')
    ORDER BY PersonStatus ASC;
END

CREATE PROCEDURE [dbo].[API_DangKyFormWeb]
    @FormName          VARCHAR(50),
    @TableName         VARCHAR(128),
    @PrimaryKey        VARCHAR(50),
    @CaptionVN         NVARCHAR(255),
    @CaptionEN         NVARCHAR(255) = NULL,
    @FormType          VARCHAR(20) = 'EDIT',
    @ViewProcedure     VARCHAR(128) = NULL,
    @ViewParameters    NVARCHAR(MAX) = NULL,
    @Overrides         NVARCHAR(MAX) = N'[]',
    @OperationProfile  VARCHAR(20) = NULL,
    @Operations        NVARCHAR(MAX) = NULL,
    @ReplaceOperations BIT = 0,
    @IncludeSaveOperation BIT = 1,
    @IncludeDeleteOperation BIT = 1,
    @EmitResult BIT = 1,
    @ApiInsertedOutput INT = NULL OUTPUT,
    @ApiDeletedOutput INT = NULL OUTPUT,
    @FieldsInsertedOutput INT = NULL OUTPUT,
    @FieldsUpdatedOutput INT = NULL OUTPUT,
    @FieldsDeletedOutput INT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @ApiInserted INT = 0;
    DECLARE @ApiDeleted INT = 0;
    DECLARE @FieldsInserted INT = 0;
    DECLARE @FieldsUpdated INT = 0;
    DECLARE @FieldsDeleted INT = 0;
    DECLARE @HasExplicitProfile BIT = CASE
        WHEN NULLIF(LTRIM(RTRIM(ISNULL(@OperationProfile, ''))), '') IS NULL THEN 0
        ELSE 1
    END;
    DECLARE @ResolvedOperationProfile VARCHAR(20);

    BEGIN TRY
        BEGIN TRANSACTION;

        IF NULLIF(LTRIM(RTRIM(@FormName)), '') IS NULL
            THROW 51000, 'FormName is required.', 1;

        IF NULLIF(LTRIM(RTRIM(@TableName)), '') IS NULL
            THROW 51001, 'TableName is required.', 1;

        IF NULLIF(LTRIM(RTRIM(@PrimaryKey)), '') IS NULL
            THROW 51002, 'PrimaryKey is required.', 1;

        IF NULLIF(LTRIM(RTRIM(@ViewProcedure)), '') IS NULL
            SET @ViewProcedure = @FormName;

        IF NULLIF(LTRIM(RTRIM(@ViewParameters)), '') IS NULL
            SET @ViewParameters = N'@Keyword=N''{Keyword}''';

        IF ISJSON(@Overrides) <> 1
            SET @Overrides = N'[]';

        IF @Operations IS NOT NULL AND ISJSON(@Operations) <> 1
            THROW 51003, 'Operations must be valid JSON.', 1;

        SET @ResolvedOperationProfile = UPPER(LTRIM(RTRIM(ISNULL(@OperationProfile, ''))));

        IF @ResolvedOperationProfile = ''
            SET @ResolvedOperationProfile = CASE
                WHEN @IncludeSaveOperation = 1 AND @IncludeDeleteOperation = 1 THEN 'CRUD'
                WHEN @IncludeSaveOperation = 0 AND @IncludeDeleteOperation = 0 THEN 'READONLY'
                ELSE 'CUSTOM'
            END;

        IF @ResolvedOperationProfile NOT IN ('CRUD', 'READONLY', 'CUSTOM')
            THROW 51007, 'OperationProfile must be CRUD, READONLY or CUSTOM.', 1;

        IF @ResolvedOperationProfile = 'CRUD'
        BEGIN
            SET @IncludeSaveOperation = 1;
            SET @IncludeDeleteOperation = 1;
        END
        ELSE IF @ResolvedOperationProfile = 'READONLY'
        BEGIN
            SET @IncludeSaveOperation = 0;
            SET @IncludeDeleteOperation = 0;
        END
        ELSE IF @HasExplicitProfile = 1
        BEGIN
            -- CUSTOM lay toan bo thao tac ghi du lieu tu @Operations.
            SET @IncludeSaveOperation = 0;
            SET @IncludeDeleteOperation = 0;
        END

        -- Profile duoc chon ro rang la hop dong chinh xac, khong giu lai API cu.
        IF @HasExplicitProfile = 1
            SET @ReplaceOperations = 1;

        DECLARE @CanonicalOperations TABLE (
            func VARCHAR(50) NOT NULL PRIMARY KEY,
            [SQL] VARCHAR(256) NOT NULL,
            Para NVARCHAR(MAX) NULL
        );

        INSERT INTO @CanonicalOperations (func, [SQL], Para)
        VALUES ('View', @ViewProcedure, @ViewParameters);

        IF @IncludeSaveOperation = 1
            INSERT INTO @CanonicalOperations (func, [SQL], Para)
            VALUES ('Save', 'API_LuuDong', N'@List=N''' + REPLACE(@FormName, '''', '''''') + N''', @Data=N''{JsonData}'', @UserName=N''{User}''');

        IF @IncludeDeleteOperation = 1
            INSERT INTO @CanonicalOperations (func, [SQL], Para)
            VALUES ('Delete', 'API_XoaDong', N'@List=N''{List}'', @Ids=N''{Ids}'', @Data=N''{JsonData}'', @UserName=N''{User}''');

        IF @Operations IS NOT NULL
        BEGIN
            IF EXISTS (
                SELECT 1
                FROM OPENJSON(@Operations)
                WITH (
                    func VARCHAR(50) '$.func',
                    [SQL] VARCHAR(256) '$.sql'
                ) operation
                WHERE NULLIF(LTRIM(RTRIM(operation.func)), '') IS NULL
                   OR NULLIF(LTRIM(RTRIM(operation.[SQL])), '') IS NULL
            )
                THROW 51004, 'Every operation requires func and sql.', 1;

            IF EXISTS (
                SELECT operation.func
                FROM OPENJSON(@Operations)
                WITH (func VARCHAR(50) '$.func') operation
                GROUP BY operation.func
                HAVING operation.func IS NULL OR COUNT(*) > 1
            )
                THROW 51005, 'Operations contains a duplicate func.', 1;

            DECLARE @ParsedOperations TABLE (
                func VARCHAR(50) NOT NULL PRIMARY KEY,
                [SQL] VARCHAR(256) NOT NULL,
                Para NVARCHAR(MAX) NULL
            );

            INSERT INTO @ParsedOperations (func, [SQL], Para)
            SELECT
                LTRIM(RTRIM(operation.func)),
                LTRIM(RTRIM(operation.[SQL])),
                operation.Para
            FROM OPENJSON(@Operations)
            WITH (
                func VARCHAR(50) '$.func',
                [SQL] VARCHAR(256) '$.sql',
                Para NVARCHAR(MAX) '$.para'
            ) operation;

            IF @ResolvedOperationProfile = 'CUSTOM'
               AND @HasExplicitProfile = 1
               AND NOT EXISTS (SELECT 1 FROM @ParsedOperations)
                THROW 51008, 'CUSTOM profile requires at least one custom operation.', 1;

            UPDATE canonical
               SET canonical.[SQL] = parsed.[SQL],
                   canonical.Para = parsed.Para
            FROM @CanonicalOperations canonical
            INNER JOIN @ParsedOperations parsed ON parsed.func = canonical.func;

            INSERT INTO @CanonicalOperations (func, [SQL], Para)
            SELECT parsed.func, parsed.[SQL], parsed.Para
            FROM @ParsedOperations parsed
            WHERE NOT EXISTS (
                SELECT 1
                FROM @CanonicalOperations canonical
                WHERE canonical.func = parsed.func
            );
        END

        IF @ResolvedOperationProfile = 'CUSTOM'
           AND @HasExplicitProfile = 1
           AND NOT EXISTS (
               SELECT 1 FROM @CanonicalOperations WHERE UPPER(func) <> 'VIEW'
           )
            THROW 51008, 'CUSTOM profile requires at least one custom operation.', 1;

        IF @ResolvedOperationProfile = 'READONLY'
           AND EXISTS (
               SELECT 1
               FROM @CanonicalOperations
               WHERE UPPER(func) IN ('SAVE', 'DELETE', 'EXECUTE')
           )
            THROW 51009, 'READONLY profile cannot contain Save, Delete or Execute.', 1;

        IF @ResolvedOperationProfile = 'CRUD'
           AND EXISTS (
               SELECT required.func
               FROM (VALUES ('View'), ('Save'), ('Delete')) required(func)
               WHERE NOT EXISTS (
                   SELECT 1
                   FROM @CanonicalOperations operation
                   WHERE UPPER(operation.func) = UPPER(required.func)
               )
           )
            THROW 51010, 'CRUD profile requires View, Save and Delete.', 1;

        IF EXISTS (
            SELECT 1
            FROM @CanonicalOperations operation
            WHERE OBJECT_ID(operation.[SQL], 'P') IS NULL
        )
            THROW 51011, 'A registered operation references a missing stored procedure.', 1;

        UPDATE form WITH (UPDLOCK, HOLDLOCK)
           SET FormType = @FormType,
               CaptionVN = @CaptionVN,
               CaptionEN = @CaptionEN,
               TableName = @TableName,
               PrimaryKey = @PrimaryKey,
               CaptionCH = COALESCE(NULLIF(form.CaptionCH, N''), @CaptionVN)
        FROM dbo.SY_FrmLstTbl form
        WHERE form.FormID = @FormName;

        IF @@ROWCOUNT = 0
        BEGIN
            INSERT INTO dbo.SY_FrmLstTbl
                (FormID, FormType, CaptionVN, CaptionEN, TableName, PrimaryKey, CaptionCH)
            VALUES
                (@FormName, @FormType, @CaptionVN, @CaptionEN, @TableName, @PrimaryKey, @CaptionVN);
        END

        IF EXISTS (
            SELECT api.func
            FROM dbo.WA_API api
            WHERE api.list = @FormName
            GROUP BY api.func
            HAVING COUNT(*) > 1
        )
            THROW 51006, 'WA_API contains duplicate list + func rows for this form.', 1;

        IF @ReplaceOperations = 1
        BEGIN
            DELETE api
            FROM dbo.WA_API api
            WHERE api.list = @FormName
              AND NOT EXISTS (
                  SELECT 1
                  FROM @CanonicalOperations operation
                  WHERE UPPER(operation.func) = UPPER(api.func)
              );

            SET @ApiDeleted = @@ROWCOUNT;
        END

        UPDATE api WITH (UPDLOCK, HOLDLOCK)
           SET api.[SQL] = operation.[SQL],
               api.Para = operation.Para
        FROM dbo.WA_API api
        INNER JOIN @CanonicalOperations operation ON operation.func = api.func
        WHERE api.list = @FormName;

        INSERT INTO dbo.WA_API (list, func, [SQL], Para)
        SELECT @FormName, operation.func, operation.[SQL], operation.Para
        FROM @CanonicalOperations operation
        WHERE NOT EXISTS (
            SELECT 1
            FROM dbo.WA_API api WITH (UPDLOCK, HOLDLOCK)
            WHERE api.list = @FormName
              AND api.func = operation.func
        );

        SET @ApiInserted = @@ROWCOUNT;

        DECLARE @SyncSummary TABLE (
            FieldsInserted INT,
            FieldsUpdated INT,
            FieldsDeleted INT
        );

        INSERT INTO @SyncSummary (FieldsInserted, FieldsUpdated, FieldsDeleted)
        EXEC dbo.API_DongBoTruongGiaoDien
            @FormName = @FormName,
            @ObjectName = @ViewProcedure,
            @Overrides = @Overrides,
            @FallbackObjectName = @TableName;

        SELECT
            @FieldsInserted = FieldsInserted,
            @FieldsUpdated = FieldsUpdated,
            @FieldsDeleted = FieldsDeleted
        FROM @SyncSummary;

        IF OBJECT_ID('dbo.SY_FmtFldTbl', 'U') IS NOT NULL
        BEGIN
            UPDATE field
               SET CaptionVN = COALESCE(formDictionary.CaptionVN, globalDictionary.CaptionVN, field.CaptionVN),
                   CaptionEN = COALESCE(formDictionary.CaptionEN, globalDictionary.CaptionEN, field.CaptionEN),
                   FormatID = COALESCE(NULLIF(field.FormatID, ''), formDictionary.FormatID, globalDictionary.FormatID, 't')
            FROM dbo.SY_FormatFields field
            OUTER APPLY (
                SELECT TOP (1) dictionary.CaptionVN, dictionary.CaptionEN, dictionary.FormatID
                FROM dbo.SY_FmtFldTbl dictionary
                WHERE dictionary.FieldName = field.FieldName
                  AND dictionary.FormName = field.FormName
            ) formDictionary
            OUTER APPLY (
                SELECT TOP (1) dictionary.CaptionVN, dictionary.CaptionEN, dictionary.FormatID
                FROM dbo.SY_FmtFldTbl dictionary
                WHERE dictionary.FieldName = field.FieldName
                  AND ISNULL(dictionary.FormName, '') = ''
            ) globalDictionary
            WHERE field.FormName = @FormName
              AND (NULLIF(field.CaptionVN, '') IS NULL OR field.CaptionVN = field.FieldName);

            SET @FieldsUpdated += @@ROWCOUNT;
        END

        ;WITH overrides AS (
            SELECT
                override.FieldName,
                override.CaptionVN,
                override.CaptionEN,
                override.FormatID,
                override.DataSource,
                override.FormPosition,
                override.ValidateRule,
                override.DependsOn,
                override.VisibleRule,
                override.OrderNo,
                override.ShowInAdd,
                override.ShowInEdit,
                override.IsReadOnlyAdd,
                override.IsReadOnlyEdit,
                override.IsRequired,
                override.ShowInFilter
            FROM OPENJSON(@Overrides)
            WITH (
                FieldName VARCHAR(128) '$.field',
                CaptionVN NVARCHAR(255) '$.captionVN',
                CaptionEN NVARCHAR(255) '$.captionEN',
                FormatID VARCHAR(10) '$.formatId',
                DataSource NVARCHAR(500) '$.dataSource',
                FormPosition VARCHAR(50) '$.position',
                ValidateRule NVARCHAR(500) '$.validateRule',
                DependsOn VARCHAR(100) '$.dependsOn',
                VisibleRule NVARCHAR(500) '$.visibleRule',
                OrderNo INT '$.orderNo',
                ShowInAdd BIT '$.showInAdd',
                ShowInEdit BIT '$.showInEdit',
                IsReadOnlyAdd BIT '$.readOnlyAdd',
                IsReadOnlyEdit BIT '$.readOnlyEdit',
                IsRequired BIT '$.required',
                ShowInFilter BIT '$.showInFilter'
            ) override
            WHERE NULLIF(LTRIM(RTRIM(override.FieldName)), '') IS NOT NULL
        )
        UPDATE field
           SET CaptionVN = COALESCE(override.CaptionVN, field.CaptionVN),
               CaptionEN = COALESCE(override.CaptionEN, field.CaptionEN),
               FormatID = COALESCE(override.FormatID, field.FormatID),
               DataSource = COALESCE(override.DataSource, field.DataSource),
               FormPosition = COALESCE(override.FormPosition, field.FormPosition),
               ValidateRule = COALESCE(override.ValidateRule, field.ValidateRule),
               DependsOn = COALESCE(override.DependsOn, field.DependsOn),
               VisibleRule = COALESCE(override.VisibleRule, field.VisibleRule),
               OrderNo = COALESCE(override.OrderNo, field.OrderNo),
               ShowInAdd = COALESCE(override.ShowInAdd, field.ShowInAdd),
               ShowInEdit = COALESCE(override.ShowInEdit, field.ShowInEdit),
               IsReadOnlyAdd = COALESCE(override.IsReadOnlyAdd, field.IsReadOnlyAdd),
               IsReadOnlyEdit = COALESCE(override.IsReadOnlyEdit, field.IsReadOnlyEdit),
               IsRequired = COALESCE(override.IsRequired, field.IsRequired),
               ShowInFilter = COALESCE(override.ShowInFilter, field.ShowInFilter)
        FROM dbo.SY_FormatFields field
        INNER JOIN overrides override ON override.FieldName = field.FieldName
        WHERE field.FormName = @FormName;

        SET @FieldsUpdated += @@ROWCOUNT;

        COMMIT TRANSACTION;

        SET @ApiInsertedOutput = @ApiInserted;
        SET @ApiDeletedOutput = @ApiDeleted;
        SET @FieldsInsertedOutput = @FieldsInserted;
        SET @FieldsUpdatedOutput = @FieldsUpdated;
        SET @FieldsDeletedOutput = @FieldsDeleted;

        IF @EmitResult = 1
            SELECT
                0 AS code,
                @FormName AS FormName,
                @ResolvedOperationProfile AS OperationProfile,
                (SELECT COUNT(*) FROM @CanonicalOperations) AS OperationCount,
                @ApiInserted AS ApiInserted,
                @ApiDeleted AS ApiDeleted,
                @FieldsInserted AS FieldsInserted,
                @FieldsUpdated AS FieldsUpdated,
                @FieldsDeleted AS FieldsDeleted,
                N'Form registration completed.' AS msg;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        THROW;
    END CATCH
END

CREATE procedure [dbo].[API_DanhSachBangCap]
