        IF NOT EXISTS (SELECT 1 FROM dbo.HR_NghiPhepTbl WHERE DocumentID = @DocumentID)
            THROW 51801, N'Đơn nghỉ phép không tồn tại.', 1;

        SELECT @BranchID = P.BranchID
